import Foundation
import Testing
@testable import HopwatchGUI

/// `link.offline` was declared on `MonitorSample.Link` but never read by its
/// lenient decoder, so the running app never had it and the offline card's
/// "Offline for X · last on Y" and precursor copy never appeared. These decode
/// lines in the exact shape `helpers/monitor_sample.py` emits (generated with
/// it, not hand-written), and pin how the card degrades when the monitor does
/// not know a piece of the context.
@Suite struct OfflineContextTests {

    /// Generated by `helpers/monitor_sample.py` with the `NETDIAG_MON_OFFLINE_*`
    /// variables below; only the `offline` object is swapped per test.
    static let offlineObject = #"{"reason":"wifi-not-joined","down_since":"2026-10-12T10:00:00Z","down_duration_s":60,"last_network":"Home","precursor":"router-unreachable"}"#

    static func line(offline: String, up: Bool = false) -> String {
        #"{"schema":2,"version":"1.15.1","ts":"2026-10-12T10:01:00Z","seq":3,"gap_s":null,"refreshed":[],"link":{"up":\#(up),"interface":null,"type":null,"ip":null,"gateway":null,"gateway_mac":null,"ssid":null,"bssid":null,"offline":\#(offline)},"network":{"id":null,"label":null,"group_id":null},"vpn":{"active":false,"type":null,"name":null},"gateway":{"loss_pct":null,"rtt_avg_ms":null,"rtt_jitter_ms":null},"internet":{"loss_pct":null,"rtt_avg_ms":null,"rtt_jitter_ms":null},"jitter_ms":null,"wifi":null,"dns":{"ok":null,"resolver":null,"elapsed_ms":null,"local_fail":null,"local":null},"tcp":{"any_ok":null,"targets":[]},"public":{"ok":null,"ip":null,"isp":null,"asn":null,"city":null,"country":null,"country_iso":null,"captive_portal":null},"status":{"severity":"ok","rules":["N1","WJ-1"],"measurement":"unknown","icmp_filtered":false,"degraded":false,"paused":false,"cadence_s":null,"auto_reconnect":null,"carry":null}}"#
    }

    static func decode(_ json: String) throws -> MonitorSample {
        try JSONDecoder().decode(MonitorSample.self, from: Data(json.utf8))
    }

    @Test func fullBlockDecodes() throws {
        let s = try Self.decode(Self.line(offline: Self.offlineObject))
        let off = try #require(s.link.offline)
        #expect(off.reason == "wifi-not-joined")
        #expect(off.downSince == "2026-10-12T10:00:00Z")
        #expect(off.downDurationS == 60)
        #expect(off.lastNetwork == "Home")
        #expect(off.precursor == "router-unreachable")
        #expect(off.statusLine == "Offline for 1m · last on Home")
        // A sample that decodes also keeps everything else.
        #expect(s.link.up == false)
        #expect(s.status.rules == ["N1", "WJ-1"])
    }

    @Test func nullBlockOnALinkUpSampleStaysNil() throws {
        let s = try Self.decode(Self.line(offline: "null", up: true))
        #expect(s.link.up)
        #expect(s.link.offline == nil)
    }

    @Test func missingBlockNeverDropsTheSample() throws {
        let json = Self.line(offline: Self.offlineObject)
            .replacingOccurrences(of: #","offline":\#(Self.offlineObject)"#, with: "")
        let s = try Self.decode(json)
        #expect(s.link.offline == nil)
        #expect(s.status.rules == ["N1", "WJ-1"])
    }

    @Test func monitorRestartShapeHasNoLastNetworkOrPrecursor() throws {
        // What a process that starts already offline emits: the shape the
        // monitor produces with NETDIAG_MON_OFFLINE_LAST_NETWORK unset.
        let obj = #"{"reason":"wifi-not-joined","down_since":"2026-10-12T10:00:50Z","down_duration_s":10,"last_network":null,"precursor":null}"#
        let off = try #require(try Self.decode(Self.line(offline: obj)).link.offline)
        #expect(off.lastNetwork == nil)
        #expect(off.knownLastNetwork == nil)
        #expect(off.precursor == nil)
        #expect(off.statusLine == "Offline for 10s", "no network clause rather than a blank or wrong one")
    }

    @Test func partialBlockKeepsWhatIsThere() throws {
        let off = try #require(try Self.decode(Self.line(offline: #"{"reason":"wifi-off"}"#)).link.offline)
        #expect(off.reason == "wifi-off")
        #expect(off.downDurationS == nil && off.lastNetwork == nil)
        #expect(off.statusLine == nil)
    }

    @Test func malformedFieldsAreDroppedIndividually() throws {
        // A string where a number belongs must not cost the sample, nor the
        // other fields of the block.
        let obj = #"{"reason":"wifi-not-joined","down_since":"2026-10-12T10:00:00Z","down_duration_s":"soon","last_network":"Home","precursor":7}"#
        let s = try Self.decode(Self.line(offline: obj))
        let off = try #require(s.link.offline)
        #expect(off.reason == "wifi-not-joined")
        #expect(off.downDurationS == nil)
        #expect(off.lastNetwork == "Home")
        #expect(off.precursor == nil)
        #expect(off.statusLine == "Last connected to Home")
        #expect(s.status.rules == ["N1", "WJ-1"])
    }

    @Test(arguments: ["[]", "\"offline\"", "42", "true"])
    func nonObjectBlockDropsTheBlockNotTheSample(_ junk: String) throws {
        let s = try Self.decode(Self.line(offline: junk))
        #expect(s.link.offline == nil)
        #expect(s.link.up == false)
        #expect(s.status.rules == ["N1", "WJ-1"])
    }

    @Test func blankNetworkNamesAreNotKnown() {
        for blank in ["", " ", "\n\t "] {
            var off = MonitorSample.OfflineContext(reason: nil, downSince: nil, downDurationS: 30,
                                                   lastNetwork: blank, precursor: nil)
            #expect(off.knownLastNetwork == nil, "\(blank.debugDescription) is not a network")
            #expect(off.statusLine == "Offline for 30s")
            off.downDurationS = nil
            #expect(off.statusLine == nil)
        }
    }

    @Test func negativeDurationIsNotShown() {
        let off = MonitorSample.OfflineContext(reason: nil, downSince: nil, downDurationS: -5,
                                               lastNetwork: "Home", precursor: nil)
        #expect(off.formattedDuration == nil)
        #expect(off.statusLine == "Last connected to Home")
    }

    @Test func liveJitterIsNilForADecodedOfflineSample() throws {
        // Reads `link.offline != nil`; it used to rely on `interface`, which
        // the monitor does not send once the route is gone.
        var s = try Self.decode(Self.line(offline: Self.offlineObject))
        s.jitterMs = 4
        #expect(s.liveJitterMs == nil)
    }
}
